$ErrorActionPreference='Stop';$module='api/LuxuryApp.Application/Modules/RecursosHumanosLuxuryApp/Nomina/NominaEncabezados';$dto="$module/DTOs";$map=[ordered]@{'GenerarNominaDTO'='GeneratePayrollDTO';'NominaEncabezadoDTO'='PayrollHeaderDTO';'NominaResumenDTO'='PayrollSummaryDTO'};$file="$dto/NominaEncabezadoDTO.cs";$content=[IO.File]::ReadAllText($file);$matches=[regex]::Matches($content,'(?ms)^public record .*?(?=^public record |\z)');foreach($m in $matches){$record=$m.Value.Trim();foreach($p in ($map.GetEnumerator()|Sort-Object {$_.Key.Length} -Descending)){$record=$record.Replace($p.Key,$p.Value)};$name=[regex]::Match($record,'^public record (\w+DTO)').Groups[1].Value;[IO.File]::WriteAllText("$dto/$name.cs","namespace RecursosHumanosLuxuryApp.Nomina.NominaEncabezados.DTOs;`r`n`r`n$record",[Text.UTF8Encoding]::new($false))};foreach($f in (Get-ChildItem $module -Recurse -Filter '*.cs')){$o=[IO.File]::ReadAllText($f.FullName);$n=$o;foreach($p in ($map.GetEnumerator()|Sort-Object {$_.Key.Length} -Descending)){$n=$n.Replace($p.Key,$p.Value)};if($n-ne$o){[IO.File]::WriteAllText($f.FullName,$n,[Text.UTF8Encoding]::new($false))}};Remove-Item $file -Force
